  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.card {
  background: var(--black-light);
  border: 1px solid rgba(255,255,255,0.05);
  padding: 2rem;
  transition: all 0.3s;
}

.card:hover {
  border-color: var(--red);
  transform: translateY(-5px);
}

.card h3 {
  font-size: 1.3rem;
  margin-bottom: 1rem;
  color: var(--red);
}

/* Two Ways Section */
.two-ways {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
}

.way-card {
  padding: 4rem 3rem;
  text-align: center;
}

.way-card h3 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.way-card p { color: var(--gray-light); }

/* Toggle */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 3rem;
}

.toggle-btn {
  font-family: 'Oswald', sans-serif;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 1rem 2.5rem;
  background: var(--black-light);
  border: 2px solid var(--red);
  color: var(--gray);
  cursor: pointer;
  transition: all 0.3s;
}

.toggle-btn:first-child { border-right: none; }
.toggle-btn:last-child { border-left: none; }

.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-content {
  display: none;
  padding: 2rem;
  background: var(--black-light);
  border: 1px solid rgba(230,57,70,0.2);
}

.toggle-content.active { display: block; }

/* Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
}

.schedule-table th, .schedule-table td {
  padding: 1.2rem 1.5rem;
  text-align: left;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.schedule-table th {
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  font-size: 0.85rem;
}

.schedule-table tr:hover { background: rgba(230,57,70,0.05); }

/* Instructor Grid */
.filter-bar {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.filter-btn {
  font-family: 'Oswald', sans-serif;
  padding: 0.6rem 1.5rem;
  background: transparent;
  border: 1px solid var(--gray);
  color: var(--gray);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: all 0.3s;
}

.filter-btn:hover, .filter-btn.active {
  border-color: var(--red);
  color: var(--red);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.instructor-card {
  background: var(--black-light);
  border: 1px solid rgba(255,255,255,0.05);
  overflow: hidden;
  transition: all 0.3s;
}

.instructor-card:hover {
  border-color: var(--red);
}

.instructor-img {
  width: 100%;
  height: 280px;
  background: linear-gradient(135deg, #2a2a2a, #1a1a1a);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--red);
}

.instructor-info { padding: 1.5rem; }

.instructor-info h3 {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

.instructor-info .location {
  color: var(--red);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 1rem;
}

/* FAQ Accordion */
.faq-list { max-width: 800px; margin: 0 auto; }

.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.faq-question {
  width: 100%;
  font-family: 'Oswald', sans-serif;
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 1.5rem 0;
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  text-align: left;
}

.faq-question:hover { color: var(--red); }

.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--red);
  transition: transform 0.3s;
}

.faq-item.active .faq-question::after { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer { max-height: 300px; }

.faq-answer p {
  padding: 0 0 1.5rem;
  color: var(--gray-light);
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  margin: 0 auto;
  max-width: 1000px;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  height: 500px;
  background: linear-gradient(135deg, #2a2a2a, #1a1a1a);
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-slide-content {
  text-align: center;
  padding: 2rem;
}

.carousel-slide-content h3 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
}

.carousel-slide-content p { color: var(--gray-light); }

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--red);
  border: none;
  width: 50px;
  height: 50px;
  cursor: pointer;
  font-size: 1.5rem;
  color: var(--white);
  transition: background 0.3s;
}

.carousel-btn:hover { background: var(--red-dark); }
.carousel-prev { left: 1rem; }
.carousel-next { right: 1rem; }

/* Newsletter */
.newsletter {
  background: var(--black-light);
  padding: 80px 2rem;
  text-align: center;
}

.newsletter h2 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.newsletter p {
  color: var(--gray);
  margin-bottom: 2rem;
}

.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 500px;
  margin: 0 auto;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-form input {
  flex: 1;
  min-width: 250px;
  padding: 1rem 1.5rem;
  background: var(--black);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  font-size: 1rem;
  outline: none;
}

.newsletter-form input:focus { border-color: var(--red); }

.newsletter-form button {
  padding: 1rem 2rem;
}

.newsletter-message {
  margin-top: 1rem;
  font-size: 0.9rem;
}

.newsletter-message.success { color: #4CAF50; }
.newsletter-message.error { color: var(--red); }

/* Footer */
.footer {
  background: var(--black);
  border-top: 1px solid rgba(255,255,255,0.05);
  padding: 60px 2rem 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 3rem;
  max-width: 1200px;
  margin: 0 auto;
}

.footer-col h4 {
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
  color: var(--red);
}

.footer-col ul { list-style: none; }

.footer-col li { margin-bottom: 0.8rem; }

.footer-col a {
  color: var(--gray);
  transition: color 0.3s;
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  max-width: 1200px;
  margin: 3rem auto 0;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.05);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p { color: var(--gray); font-size: 0.85rem; }

.country-selector {
  position: relative;
}

.country-selector button {
  background: transparent;
  border: 1px solid var(--gray);
  color: var(--gray);
  padding: 0.5rem 1rem;
  cursor: pointer;
  font-size: 0.85rem;
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  background: var(--black-light);
  border: 1px solid var(--red);
  display: none;
  min-width: 150px;
}

.country-dropdown.show { display: block; }

.country-dropdown a {
  display: block;
  padding: 0.8rem 1rem;
  color: var(--gray-light);
}

.country-dropdown a:hover { background: var(--red); color: var(--white); }

/* Features */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.feature-card {
  text-align: center;
  padding: 2rem;
}

.feature-card .icon {
  width: 60px;
  height: 60px;
  background: var(--red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
  font-size: 1.5rem;
}

.feature-card h3 {
  font-size: 1.2rem;
  margin-bottom: 1rem;
}

.feature-card p { color: var(--gray); }

/* CTA Section */
.cta-section {
  background: linear-gradient(135deg, rgba(230,57,70,0.2), rgba(17,17,17,0.95));
  text-align: center;
  padding: 100px 2rem;
}

.cta-section h2 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 1rem;
}

.cta-section p {
  color: var(--gray-light);
  margin-bottom: 2rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-toggle { display: flex; }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: var(--black);
    padding: 2rem;
    gap: 1.5rem;
  }

  .two-ways { grid-template-columns: 1fr; }

  .hero-buttons { flex-direction: column; }

  .newsletter-form { flex-direction: column; }

  .schedule-table { font-size: 0.85rem; }
  .schedule-table th, .schedule-table td { padding: 0.8rem; }

  .footer-bottom { flex-direction: column; text-align: center; }
}
